export default function WhyChooseUs() {
  const [isVisible, setIsVisible] = useState(false);
  const [halfOffset, setHalfOffset] = useState<number>(230);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRef = useRef<HTMLElement>(null);
  const firstCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  // Dynamically lock the black background bottom to the EXACT 50% midpoint of the first row cards
  useEffect(() => {
    const updateOffset = () => {
      if (firstCardRef.current && sectionRef.current) {
        const cardRect = firstCardRef.current.getBoundingClientRect();
        const sectionRect = sectionRef.current.getBoundingClientRect();
        const midPoint =
          cardRect.top - sectionRect.top + cardRect.height * 0.5;
        if (midPoint > 0) {
          setHalfOffset(midPoint);
        }
      }
    };

    updateOffset();
    window.addEventListener("resize", updateOffset);
    const timer = setTimeout(updateOffset, 150);

    return () => {
      window.removeEventListener("resize", updateOffset);
      clearTimeout(timer);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="w-full bg-white select-none overflow-hidden pt-8 sm:pt-12 lg:pt-14 pb-16 sm:pb-20 lg:pb-28"
    >
      {/* Contained section with black top banner ALIGNED with the cards grid with 48px side gap */}
      <section
        ref={sectionRef}
        className="relative w-full max-w-6xl mx-auto px-4 sm:px-6 lg:px-0"
      >
        {/* Dynamic Black Top Banner with 45-48px side padding so cards sit comfortably inside */}
        <div
          className="absolute top-0 -inset-x-3 sm:-inset-x-6 lg:-inset-x-11 xl:-inset-x-12 bg-[#181818] z-0 transition-all duration-300 pointer-events-none rounded-2xl sm:rounded-3xl"
          style={{ height: `${halfOffset}px` }}
        />

        {/* Title inside dark banner */}
        <div
          className={`relative z-10 flex justify-center text-center pt-8 sm:pt-10 lg:pt-12 mb-8 sm:mb-9 lg:mb-10 transition-all duration-800 ease-[cubic-bezier(0.16,1,0.3,1)] ${isVisible ? "opacity-100 translate-y-0" : "opacity-0 -translate-y-6"
            }`}
        >
          <h2
            className="text-[32px] sm:text-[38px] md:text-[44px] font-normal leading-none tracking-wide uppercase text-white px-4"
            style={{
              fontFamily: 'var(--font-bebas-neue), "Bebas Neue", sans-serif',
              fontWeight: 400,
            }}
          >
            WHY WE CHOOSE US
          </h2>
        </div>

        {/* 6 Feature Cards Grid */}
        <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-7 lg:gap-8">
          {features.map((feature, index) => {
            const delays = [
              "delay-100",
              "delay-200",
              "delay-300",
              "delay-200",
              "delay-300",
              "delay-400",
            ];

            return (
              <div
                key={feature.id}
                ref={index === 0 ? firstCardRef : undefined}
                className={`group relative bg-white rounded-2xl sm:rounded-[22px] border border-neutral-200/90 p-7 sm:p-8 lg:p-9 flex flex-col items-center text-center shadow-[0_8px_24px_rgba(0,0,0,0.06)] hover:shadow-[0_14px_36px_rgba(0,0,0,0.1)] hover:-translate-y-1.5 transition-all duration-400 ease-out ${delays[index]
                  } ${isVisible
                    ? "opacity-100 translate-y-0"
                    : "opacity-0 translate-y-12"
                  }`}
              >
                {/* Top Red SVG Icon */}
                <div className="mb-4 sm:mb-5 transition-transform duration-300 group-hover:scale-110 flex items-center justify-center">
                  {feature.icon}
                </div>

                {/* Title */}
                <h3
                  className="text-[20px] sm:text-[22px] md:text-[23px] leading-tight tracking-wide text-[#181818] uppercase mb-2.5 sm:mb-3"
                  style={{
                    fontFamily:
                      'var(--font-bebas-neue), "Bebas Neue", sans-serif',
                    fontWeight: 400,
                  }}
                >
                  {feature.title}
                </h3>

                {/* Description */}
                <p
                  className="text-[13.5px] sm:text-[14.5px] text-neutral-600 leading-[1.65] sm:leading-[1.7] font-normal max-w-[290px] mx-auto"
                  style={{
                    fontFamily:
                      'var(--font-open-sans), "Open Sans", sans-serif',
                  }}
                >
                  {feature.description}
                </p>
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
}
